<?php
declare(strict_types=1);namespace Moves\Services;
use DateTimeImmutable;use InvalidArgumentException;use MovesCode\Model\Connection;use PDO;
/** Ordens de serviço isoladas por empresa, sem efeito em saldo bancário. */
final class ServiceOrders
{
 private PDO $pdo;private int $contextId;public function __construct(private readonly int$organizationId){$this->pdo=Connection::get();$this->contextId=FinanceContext::forOrganization($organizationId);}
 public function create(array$data,int$userId,array$files=[]):array{$key=$this->key($data['idempotency_key']??null);if(($id=$this->byKey($key))!==null)return['id'=>$id,'duplicate'=>true];$f=$this->fields($data);$items=$this->items($data);OrganizationFiles::validate($files);$stored=[];$this->pdo->beginTransaction();try{$number=$this->nextNumber();[$subtotal,$discount,$total]=$this->totals($items,$f['discount_cents']);$q=$this->pdo->prepare('INSERT INTO organization_service_orders (organization_id,financial_context_id,order_number,customer_contact_id,description,responsible_user_id,start_date,due_date,status,subtotal_cents,discount_cents,total_cents,notes,idempotency_key,created_by) VALUES (?,?,?,?,?,?,?,?,\'draft\',?,?,?,?,?,?)');$q->execute([$this->organizationId,$this->contextId,$number,$f['customer_id'],$f['description'],$f['responsible_user_id'],$f['start_date'],$f['due_date'],$subtotal,$discount,$total,$f['notes'],$key,$userId]);$id=(int)$this->pdo->lastInsertId();$this->replaceItems($id,$items);foreach($files as$file){$saved=OrganizationFiles::store($this->organizationId,'service-orders',$file);$stored[]=$saved['path'];$this->pdo->prepare('INSERT INTO organization_service_order_attachments (service_order_id,organization_id,uploaded_by,stored_path,original_name,mime_type,size_bytes) VALUES (?,?,?,?,?,?,?)')->execute([$id,$this->organizationId,$userId,$saved['path'],$saved['name'],$saved['mime'],$saved['size']]);}$this->history($id,'created',$userId,['number'=>$number,'total_cents'=>$total]);$this->pdo->commit();return['id'=>$id,'duplicate'=>false];}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();foreach($stored as$p)OrganizationFiles::remove($this->organizationId,'service-orders',$p);if($e instanceof \PDOException&&$e->getCode()==='23000'&&($id=$this->byKey($key))!==null)return['id'=>$id,'duplicate'=>true];throw$e;}}
 public function update(int$id,array$data,int$userId,array$files=[]):void{$current=$this->find($id);if($current['status']==='cancelled'||$current['receivable_entry_id']!==null)throw new InvalidArgumentException('Ordem cancelada ou já cobrada não pode ter valores alterados.');$f=$this->fields($data);$items=$this->items($data);[$subtotal,$discount,$total]=$this->totals($items,$f['discount_cents']);OrganizationFiles::validate($files);$stored=[];$this->pdo->beginTransaction();try{$this->pdo->prepare('UPDATE organization_service_orders SET customer_contact_id=?,description=?,responsible_user_id=?,start_date=?,due_date=?,subtotal_cents=?,discount_cents=?,total_cents=?,notes=? WHERE id=? AND organization_id=?')->execute([$f['customer_id'],$f['description'],$f['responsible_user_id'],$f['start_date'],$f['due_date'],$subtotal,$discount,$total,$f['notes'],$id,$this->organizationId]);$this->replaceItems($id,$items);foreach($files as$file){$saved=OrganizationFiles::store($this->organizationId,'service-orders',$file);$stored[]=$saved['path'];$this->pdo->prepare('INSERT INTO organization_service_order_attachments (service_order_id,organization_id,uploaded_by,stored_path,original_name,mime_type,size_bytes) VALUES (?,?,?,?,?,?,?)')->execute([$id,$this->organizationId,$userId,$saved['path'],$saved['name'],$saved['mime'],$saved['size']]);}$this->history($id,'updated',$userId,['total_cents'=>$total]);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();foreach($stored as$p)OrganizationFiles::remove($this->organizationId,'service-orders',$p);throw$e;}}
 public function setStatus(int$id,string$status,int$userId):void{if(!in_array($status,['draft','open','in_progress','completed','cancelled'],true))throw new InvalidArgumentException('Situação inválida.');$current=$this->find($id);if($current['status']==='cancelled'&&$status!=='cancelled')throw new InvalidArgumentException('Ordem cancelada não pode ser reaberta.');$this->pdo->prepare('UPDATE organization_service_orders SET status=? WHERE id=? AND organization_id=?')->execute([$status,$id,$this->organizationId]);$this->history($id,'status_changed',$userId,['from'=>$current['status'],'to'=>$status]);}
 public function generateReceivable(int$id,array$data,int$userId):array{$order=$this->find($id);if($order['status']==='cancelled')throw new InvalidArgumentException('Ordem cancelada não pode gerar cobrança.');if($order['receivable_entry_id']!==null)return['entry_id'=>(int)$order['receivable_entry_id'],'duplicate'=>true];if((int)$order['total_cents']<=0)throw new InvalidArgumentException('A ordem precisa ter valor positivo.');$customer=(new Contacts($this->contextId))->find((int)$order['customer_contact_id']);$due=$this->date($data['due_date']??$order['due_date']??null);$result=(new Receivables($this->contextId))->create(['description'=>'OS '.$order['order_number'].' - '.($order['description']?:'Serviços'),'amount'=>number_format((int)$order['total_cents']/100,2,',','.'),'due_date'=>$due,'competence'=>substr($due,0,7),'account_id'=>$data['account_id']??null,'category_id'=>$data['category_id']??null,'contact_id'=>$order['customer_contact_id'],'counterparty_name'=>$customer['trade_name']?:$customer['legal_name'],'document_number'=>$order['order_number'],'payment_method'=>$data['payment_method']??'other','idempotency_key'=>hash('sha256','service-order-receivable-'.$this->organizationId.'-'.$id)],$userId);$this->pdo->prepare('UPDATE organization_service_orders SET receivable_entry_id=COALESCE(receivable_entry_id,?) WHERE id=? AND organization_id=?')->execute([$result['id'],$id,$this->organizationId]);$this->history($id,'receivable_created',$userId,['entry_id'=>$result['id']]);return['entry_id'=>$result['id'],'duplicate'=>$result['duplicate']];}
 public function listing(array$filters=[]):array{$where=['o.organization_id=?'];$args=[$this->organizationId];if(in_array($filters['status']??'', ['draft','open','in_progress','completed','cancelled'],true)){$where[]='o.status=?';$args[]=$filters['status'];}if(!empty($filters['customer_id'])){$where[]='o.customer_contact_id=?';$args[]=(int)$filters['customer_id'];}$q=$this->pdo->prepare('SELECT o.*,COALESCE(NULLIF(c.trade_name,\'\'),c.legal_name) customer_name,TRIM(CONCAT_WS(\' \',u.first_name,u.last_name)) responsible_name FROM organization_service_orders o INNER JOIN finance_contacts c ON c.id=o.customer_contact_id AND c.financial_context_id=o.financial_context_id LEFT JOIN users u ON u.id=o.responsible_user_id WHERE '.implode(' AND ',$where).' ORDER BY o.id DESC');$q->execute($args);$rows=$q->fetchAll(PDO::FETCH_ASSOC);foreach($rows as&$row){$row['items']=$this->orderItems((int)$row['id']);$row['attachments']=$this->attachments((int)$row['id']);$row['history']=$this->historyRows((int)$row['id']);}$ind=['draft'=>0,'open'=>0,'in_progress'=>0,'completed'=>0,'cancelled'=>0];foreach($rows as$row)$ind[$row['status']]++;return['rows'=>$rows,'indicators'=>$ind];}
 public function find(int$id):array{$q=$this->pdo->prepare('SELECT * FROM organization_service_orders WHERE id=? AND organization_id=?');$q->execute([$id,$this->organizationId]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new InvalidArgumentException('Ordem de serviço não encontrada.');return$r;}
 public function attachment(int$id):?array{$q=$this->pdo->prepare('SELECT * FROM organization_service_order_attachments WHERE id=? AND organization_id=?');$q->execute([$id,$this->organizationId]);return$q->fetch(PDO::FETCH_ASSOC)?:null;}
 public function historyRows(int$id):array{$this->find($id);$q=$this->pdo->prepare('SELECT h.*,TRIM(CONCAT_WS(\' \',u.first_name,u.last_name)) actor_name FROM organization_service_order_history h LEFT JOIN users u ON u.id=h.actor_user_id WHERE h.service_order_id=? AND h.organization_id=? ORDER BY h.id DESC');$q->execute([$id,$this->organizationId]);return$q->fetchAll(PDO::FETCH_ASSOC);}
 private function fields(array$d):array{$customer=filter_var($d['customer_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($customer===false)throw new InvalidArgumentException('Escolha o cliente.');$contact=(new Contacts($this->contextId))->find((int)$customer);if((int)$contact['is_customer']!==1||$contact['status']!=='active')throw new InvalidArgumentException('Escolha um cliente ativo.');$responsible=$this->responsible($d['responsible_user_id']??null);return['customer_id'=>(int)$customer,'description'=>$this->text($d['description']??null,5000),'responsible_user_id'=>$responsible,'start_date'=>$this->optionalDate($d['start_date']??null),'due_date'=>$this->optionalDate($d['due_date']??null),'discount_cents'=>$this->zeroCents($d['discount']??null),'notes'=>$this->text($d['notes']??null,5000)];}
 private function items(array$d):array{$descriptions=is_array($d['item_description']??null)?$d['item_description']:[];$types=is_array($d['item_type']??null)?$d['item_type']:[];$quantities=is_array($d['item_quantity']??null)?$d['item_quantity']:[];$prices=is_array($d['item_unit_price']??null)?$d['item_unit_price']:[];$discounts=is_array($d['item_discount']??null)?$d['item_discount']:[];$items=[];foreach($descriptions as$i=>$description){$description=trim((string)$description);if($description==='')continue;$quantity=$this->quantity($quantities[$i]??null);$unit=Finance::parseCents($prices[$i]??null);$discount=$this->zeroCents($discounts[$i]??null);$gross=intdiv($quantity*$unit,1000);if($discount>$gross)throw new InvalidArgumentException('Desconto do item acima do valor bruto.');$items[]=['type'=>in_array($types[$i]??'service',['service','item'],true)?$types[$i]:'service','description'=>mb_substr($description,0,255),'quantity'=>$quantity,'unit'=>$unit,'discount'=>$discount,'total'=>$gross-$discount];}if($items===[])throw new InvalidArgumentException('Adicione ao menos um serviço ou item.');return$items;}
 private function totals(array$items,int$orderDiscount):array{$subtotal=array_sum(array_column($items,'total'));if($orderDiscount>$subtotal)throw new InvalidArgumentException('Desconto geral acima do subtotal.');return[$subtotal,$orderDiscount,$subtotal-$orderDiscount];}
 private function replaceItems(int$id,array$items):void{$this->pdo->prepare('DELETE FROM organization_service_order_items WHERE service_order_id=?')->execute([$id]);$q=$this->pdo->prepare('INSERT INTO organization_service_order_items (service_order_id,item_type,description,quantity_milli,unit_price_cents,discount_cents,total_cents) VALUES (?,?,?,?,?,?,?)');foreach($items as$item)$q->execute([$id,$item['type'],$item['description'],$item['quantity'],$item['unit'],$item['discount'],$item['total']]);}
 private function orderItems(int$id):array{$q=$this->pdo->prepare('SELECT * FROM organization_service_order_items WHERE service_order_id=? ORDER BY id');$q->execute([$id]);return$q->fetchAll(PDO::FETCH_ASSOC);}
 private function attachments(int$id):array{$q=$this->pdo->prepare('SELECT id,original_name,size_bytes FROM organization_service_order_attachments WHERE service_order_id=? AND organization_id=? ORDER BY id');$q->execute([$id,$this->organizationId]);return$q->fetchAll(PDO::FETCH_ASSOC);}
 private function nextNumber():string{$year=(int)date('Y');$this->pdo->prepare('INSERT INTO organization_service_order_sequences (organization_id,sequence_year,current_number) VALUES (?,?,1) ON DUPLICATE KEY UPDATE current_number=LAST_INSERT_ID(current_number+1)')->execute([$this->organizationId,$year]);$current=(int)$this->pdo->lastInsertId();if($current===0){$q=$this->pdo->prepare('SELECT current_number FROM organization_service_order_sequences WHERE organization_id=? AND sequence_year=?');$q->execute([$this->organizationId,$year]);$current=(int)$q->fetchColumn();}return sprintf('OS-%d-%06d',$year,$current);}
 private function history(int$id,string$action,?int$user,array$meta=[]):void{$this->pdo->prepare('INSERT INTO organization_service_order_history (service_order_id,organization_id,actor_user_id,action,metadata_json) VALUES (?,?,?,?,?)')->execute([$id,$this->organizationId,$user,$action,$meta===[]?null:json_encode($meta,JSON_THROW_ON_ERROR)]);}
 private function responsible(mixed$id):?int{if($id===null||$id==='')return null;$id=filter_var($id,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$q=$this->pdo->prepare("SELECT user_id FROM organization_members WHERE organization_id=? AND user_id=? AND status='active'");$q->execute([$this->organizationId,$id===false?0:$id]);if($id===false||$q->fetchColumn()===false)throw new InvalidArgumentException('Responsável inválido.');return(int)$id;}
 private function byKey(string$key):?int{$q=$this->pdo->prepare('SELECT id FROM organization_service_orders WHERE organization_id=? AND idempotency_key=?');$q->execute([$this->organizationId,$key]);$id=$q->fetchColumn();return$id===false?null:(int)$id;}
 private function key(mixed$v):string{$v=is_string($v)?trim($v):'';if(!preg_match('/^[a-f0-9]{32,64}$/',$v))throw new InvalidArgumentException('Solicitação inválida. Atualize a página.');return$v;}
 private function quantity(mixed$v):int{$v=str_replace(',','.',trim((string)$v));if(!preg_match('/^\d+(\.\d{1,3})?$/',$v))throw new InvalidArgumentException('Quantidade inválida.');$milli=(int)round((float)$v*1000);if($milli<=0)throw new InvalidArgumentException('Quantidade deve ser positiva.');return$milli;}
 private function zeroCents(mixed$v):int{$v=trim((string)$v);if($v===''||preg_match('/^0+(?:[,.]0{1,2})?$/',$v))return 0;return Finance::parseCents($v);}
 private function date(mixed$v):string{$d=is_string($v)?DateTimeImmutable::createFromFormat('!Y-m-d',$v):false;if(!$d||$d->format('Y-m-d')!==$v)throw new InvalidArgumentException('Data inválida.');return$v;}
 private function optionalDate(mixed$v):?string{return$v===null||$v===''?null:$this->date($v);}
 private function text(mixed$v,int$max):?string{$v=trim((string)$v);if($v==='')return null;if(mb_strlen($v)>$max)throw new InvalidArgumentException('Texto acima do limite.');return$v;}
}
